SELECT p.status, p.close_reason, COUNT(*) AS n, ROUND(SUM(p.realized_pnl), 6) AS pnl_sum, MIN(p.closed_at) AS first_closed, MAX(p.closed_at) AS last_closed FROM paper_position p WHERE p.closed_at IS NOT NULL AND p.realized_pnl < 0 AND p.closed_at >= (SELECT x.closed_at FROM paper_position x WHERE x.id = 137) AND p.closed_at <= '2026-10-12 18:00:04' GROUP BY p.status, p.close_reason ORDER BY pnl_sum